export BASHSV_DIR=$PWD/sv BASHSV_RUNDIR=$PWD/run BASHSV_LOGDIR=$PWD/log USER=w5user
export BASHCRON_SPOOL_DIR=$PWD/spool
mkdir -p marks log run
chmod 755 sv/*/run sv/*/check sv/*/finish 2>/dev/null
nap() { read -t "$1" -u 7 _; return 0; }
waitfor() { local n=0; until eval "$1"; do (( ++n > 300 )) && return 1; nap 0.05; done; }
alive() { local l; [[ -d /proc/$1 ]] && read -r l </proc/$1/stat && [[ ${l##*) } != Z* ]]; }
gone() { ! alive "$1"; }
rd() { local v=; [[ -r $1 ]] && read -r v <"$1"; printf '%s' "$v"; }
lines() { local n=0 l; [[ -r $1 ]] && while read -r l; do ((n++)); done <"$1"; printf '%s' "$n"; }
yn() { if "$@"; then printf yes; else printf no; fi; }
stopall() { local s sp; for s in "$@"; do sp=$(rd run/$s/super-pid); sv down "$s" >/dev/null 2>&1; [[ -n $sp ]] && waitfor "gone $sp"; waitfor "[[ ! -e run/$s/super-pid ]]"; done; nap 0.3; }
[[ $(type -t sv) == builtin ]] || exit 99
chmod 1777 marks
/usr/bin/mount --bind "$BASH" /bin/bash || exit 90
for t in mnt uts ipc net pid cgroup user; do echo "$t $(/usr/bin/readlink /proc/self/ns/$t)"; done > marks/base.ns
differs() { local -A a b; local t v out=
  while read -r t v; do a[$t]=$v; done <marks/base.ns
  while read -r t v; do b[$t]=$v; done <marks/$1.ns
  for t in mnt uts ipc net pid cgroup user; do [[ -n ${b[$t]} && ${a[$t]} != "${b[$t]}" ]] && out+="$t,"; done
  [[ -n ${b[user]} ]] || out+=missing-output
  printf '%s' "${out%,}"; }
selfpid() { local t v; while read -r t v; do [[ $t == self ]] && printf '%s' "$v"; done <marks/$1.ns; }
for n in nsnone nsmount nsuts nsipc nsnet nspid nscgroup nsuser nsmulti; do
  sv once $n >o.$n 2>e.$n; echo "$n: rc=$? changed=[$(differs $n)]"
done
echo "pid-namespace-service-is-pid1=$([[ $(selfpid nspid) == 1 ]] && echo yes || echo no) others-not-pid1=$([[ $(selfpid nsuts) != 1 ]] && echo yes || echo no)"
